  {t="A", seg=11, q={387}, names={"Quell The Uprising"}, text="Warden Thelwater, at the Stockade door. Kill 10 Defias Prisoners, 8 Convicts and 8 Insurgents.", zone="Stormwind City", map=1453, x=41.1, y=58.1, dg=3},
