  {t="A", seg=11, q={1245}, names={"The Missing Diplomat"}, text="Watcher Backus", zone="Duskwood", map=1431, x=74.8, y=44.2},
  {t="T", seg=11, q={96137}, names={"Ira's Dagger"}, text="Sirra Von'Indi, town hall (only if you did Ira's Dagger)", zone="Duskwood", map=1431, x=72.6, y=47.5},
  {t="T", seg=11, q={96138}, names={"Merrick's Bow"}, text="Sirra Von'Indi (only if you did Merrick's Bow)", zone="Duskwood", map=1431, x=72.6, y=47.5},
  {t="A", seg=11, q={98447}, names={"The Valor Family"}, text="Sirra Von'Indi (new in Forever). Its text says it follows the two weapon quests; if she does not offer it, skip its steps. If you only finish the weapons on the last loop, take it then and decide whether one more Raven Hill trip is worth 2200 XP", zone="Duskwood", map=1431, x=72.6, y=47.5},
  {t="FLY", seg=11, arg="Stormwind", text="Felicia Maline, Darkshire", zone="Duskwood", map=1431, x=77.5, y=44.3},
  {t="T", seg=11, q={69}, names={"The Legend of Stalvan"}, text="Leave Stormwind by the main gate and run to Goldshire (2 minutes). Innkeeper Farley in the Lion's Pride Inn", zone="Elwynn Forest", map=1429, x=43.8, y=65.8},
  {t="A", seg=11, q={70}, names={"The Legend of Stalvan"}, text="Innkeeper Farley. Then open the chest upstairs in the inn for Stalvan's Undelivered Letter", zone="Elwynn Forest", map=1429, x=43.8, y=65.8},
  {t="T", seg=11, q={1245}, names={"The Missing Diplomat"}, text="Back into Stormwind. Elling Trias, in the cheese shop", zone="Stormwind City", map=1453, x=66.0, y=74.1},
