  {t="A", seg=15, q={185}, names={"Tiger Mastery"}, text="Ajeck Rouack", zone="Stranglethorn Vale", map=1434, x=35.6, y=10.6},
  {t="A", seg=15, q={190}, names={"Panther Mastery"}, text="Sir S. J. Erlgadin", zone="Stranglethorn Vale", map=1434, x=35.5, y=10.6},
  {t="C", seg=15, q={185,190}, names={"Tiger Mastery","Panther Mastery"}, text="10 Young Stranglethorn Tigers and 10 Young Panthers (30-31), all around the camp and east of it towards the river", zone="Stranglethorn Vale", map=1434, x=38.0, y=12.0},
  {t="C", seg=15, q={203,204}, names={"The Second Rebellion","Bad Medicine"}, text="Kurzen's Compound, the walled camp east across the river. Kill 15 Kurzen Jungle Fighters; they and the Medicine Men drop the 7 Jungle Remedies. The Venom Fern Extract is in a Kurzen Supplies crate inside the compound (44.1, 9.5). The Medicine Men heal and a warlock has no interrupt: kill them first, with Curse of Tongues on them to slow the heal, or Fear the Medicine Man while you kill the fighter beside him. Voidwalker first on every pull.", zone="Stranglethorn Vale", map=1434, x=44.9, y=10.3},
  {t="T", seg=15, q={200}, names={"Bookie Herod"}, text="Bookie Herod's Records, a book on the upper floor of the big building in the compound", zone="Stranglethorn Vale", map=1434, x=43.7, y=9.4},
  {t="A", seg=15, q={328}, names={"The Hidden Key"}, text="Bookie Herod's Records. You get a Small Brass Key.", zone="Stranglethorn Vale", map=1434, x=43.7, y=9.4},
  {t="T", seg=15, q={203}, names={"The Second Rebellion"}, text="Sergeant Yohwa, back at the Rebel Camp", zone="Stranglethorn Vale", map=1434, x=38.0, y=3.3},
  {t="T", seg=15, q={204}, names={"Bad Medicine"}, text="Sergeant Yohwa", zone="Stranglethorn Vale", map=1434, x=38.0, y=3.3},
  {t="A", seg=15, q={574}, names={"Special Forces"}, text="Sergeant Yohwa", zone="Stranglethorn Vale", map=1434, x=38.0, y=3.3},
  {t="A", seg=15, q={207}, names={"Kurzen's Mystery"}, text="Brother Nimetz", zone="Stranglethorn Vale", map=1434, x=37.8, y=3.6},
  {t="C", seg=15, q={574}, names={"Special Forces"}, text="The cave at the back (north-east) of Kurzen's Compound: 10 Kurzen Commandos (33-35, they stealth) and 6 Kurzen Headshrinkers (34-35, casters: kill them first, with Curse of Tongues on them, or Fear one while the Voidwalker holds the other enemy). Do not go down to Colonel Kurzen himself.", zone="Stranglethorn Vale", map=1434, x=46.4, y=7.7, path={{45.6,7.2}}, cave=true},
  {t="T", seg=15, q={328}, names={"The Hidden Key"}, text="Bookie Herod's Strongbox, deep in the same cave", zone="Stranglethorn Vale", map=1434, x=49.6, y=7.6, path={{45.6,7.2}}, cave=true},
  {t="A", seg=15, q={329}, names={"The Spy Revealed!"}, text="Bookie Herod's Strongbox", zone="Stranglethorn Vale", map=1434, x=49.6, y=7.6},
