  {t="A", seg=15, q={330}, names={"Patrol Schedules"}, text="Lieutenant Doren", zone="Stranglethorn Vale", map=1434, x=38.0, y=3.0},
  {t="T", seg=15, q={330}, names={"Patrol Schedules"}, text="Corporal Sethman, a few steps away", zone="Stranglethorn Vale", map=1434, x=37.7, y=3.4},
  {t="A", seg=15, q={331}, names={"Report to Doren"}, text="Corporal Sethman", zone="Stranglethorn Vale", map=1434, x=37.7, y=3.4},
