  {t="C", seg=15, q={187}, names={"Tiger Mastery"}, text="10 Elder Stranglethorn Tigers (34-35), south-west of the camp near the Tkashi Ruins", zone="Stranglethorn Vale", map=1434, x=33.4, y=18.5},
  {t="C", seg=15, q={195}, names={"Raptor Mastery"}, text="10 Lashtail Raptors (35-36), further south on both sides of the road", zone="Stranglethorn Vale", map=1434, x=35.1, y=23.3},
