  {t="A", seg=15, q={188}, names={"Tiger Mastery"}, text="Ajeck Rouack", zone="Stranglethorn Vale", map=1434, x=35.6, y=10.6},
  {t="C", seg=15, q={188}, names={"Tiger Mastery"}, text="Sin'Dall (37), a white tigress on top of the small hill where the elder tigers are. Take her paw.", zone="Stranglethorn Vale", map=1434, x=32.2, y=17.4, path={{31.2,15.4},{31.2,17.2}}},
